def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def ranges(n, cuts):
        result, start = [], 0
        for x in cuts:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result

    rs = ranges(h, sep_rows)
    cs = ranges(w, sep_cols)
    out = [row[:] for row in grid]

    source = None
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                source = (ri, ci, r0, r1, c0, c1)
                break
        if source:
            break

    if source:
        sri, sci, r0, r1, c0, c1 = source
        pattern = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
        for ri, (a, b) in enumerate(rs):
            for ci, (x, y) in enumerate(cs):
                if (ri, ci) == (sri, sci):
                    continue
                for dr in range(min(b - a, len(pattern))):
                    for dc in range(min(y - x, len(pattern[0]))):
                        if pattern[dr][dc] != bg:
                            out[a + dr][x + dc] = pattern[dr][dc]
    return out
